                                        //Variables para lecturas\nint humid = 0;\nint pressure = 0;\n\n//InfluxDBClient client(INFLUXDB_URL, INFLUXDB_ORG, INFLUXDB_BUCKET, INFLUXDB_TOKEN, InfluxDbCloud2CACert); //Cliente InfluxDB con certificado preconfigurado\nInfluxDBClient client(INFLUXDB_URL, INFLUXDB_ORG, INFLUXDB_BUCKET, INFLUXDB_TOKEN);\n\nPoint sensor("weather");                                            //Punto de datos\n\nvoid setup()\n{\n  Serial.begin(115200);                                             //Iniciar comunicaci\xf3n serie\n\n  dht.begin();                                                      //Conexi\xf3n con DHT\n  if(!bmp280.init())                                                //Conexi\xf3n con BMP280\n    Serial.println("bmp280 init error!");\n\n  WiFi.mode(WIFI_STA);                                              //Configurar wifi\n  wifiMulti.addAP(WIFI_SSID, WIFI_PASSWORD);\n\n  Serial.print("Connecting to wifi");                               //Conectar a WiFi\n  while (wifiMulti.run() != WL_CONNECTED)\n  {\n    Serial.print(".");\n    delay(100);\n  }\n  Serial.println();\n\n  sensor.addTag("device", DEVICE);                                   //Agregar tag(s)\n  sensor.addTag("SSID", WIFI_SSID);\n\n  timeSync(TZ_INFO, "pool.ntp.org", "time.nis.gov");                 //Sincronizar hora para validaci\xf3n de certificados\n\n  if (client.validateConnection())                                   //Verificar conexi\xf3n con servidor\n  {\n    Serial.print("Connected to InfluxDB: ");\n    Serial.println(client.getServerUrl());\n  }\n  else\n  {\n    Serial.print("InfluxDB connection failed: ");\n    Serial.println(client.getLastErrorMessage());\n  }\n}\n\nvoid loop()\n{\n  temp = dht.readTemperature();                                      //Leer temp\n  humid = dht.readHumidity();                                        //Leer humedad\n  pressure = bmp280.getPressure()/100;                               //Leer presi\xf3n\n\n  sensor.clearFields();                                              //Limpiar campos\n\n  sensor.addField("temperature", temp);                              //Almacenar valor medido\n  sensor.addField("humidity", humid);\n  sensor.addField("pressure", pressure);\n\n  if (wifiMulti.run() != WL_CONNECTED)\n    Serial.println("Wifi connection lost");\n\n  if (!client.writePoint(sensor))\n  {\n    Serial.print("InfluxDB write failed: ");\n    Serial.println(client.getLastErrorMessage());\n  }\n\n  Serial.print("Temp: ");\n  Serial.println(temp);\n  Serial.print("Humidity: ");\n  Serial.println(humid);\n  Serial.print("Pressure: ");\n  Serial.println(pressure);\n  delay(1000);\n}\n'})}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Nota:"})," Este c\xf3digo no est\xe1 completo. Si configuras tu token de API y bucket, el c\xf3digo generado en la p\xe1gina de interfaz de Arduino (accesible desde tu panel de InfluxDB) ya contendr\xe1 la configuraci\xf3n correcta, solo tienes que copiarlo."]}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.img,{src:"https://www.the-diy-life.com/wp-content/uploads/2021/12/InfluxDB-Arduino-Interface-Instructions-1024x576.jpg",alt:"Instrucciones de la interfaz Arduino InfluxDB"})}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Paso 3."})," Sube el c\xf3digo y revisa los resultados."]}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:(0,r.jsx)(n.img,{src:"https://files.seeedstudio.com/wiki/ESP32-InfluxDB-Grafana/image-20220124140133524.png",alt:"image-20220124140133524"})}),"\n",(0,r.jsx)(n.p,{children:"Despu\xe9s de un tiempo, veremos la informaci\xf3n disponible en la base de datos InfluxDB, confirmando que el ESP32 funciona correctamente. Ahora instalaremos Grafana en nuestro reTerminal y lo configuraremos para mostrar la informaci\xf3n."}),"\n",(0,r.jsx)(n.h2,{id:"instalar-y-configurar-grafana-en-el-reterminal",children:"Instalar y configurar Grafana en el reTerminal"}),"\n",(0,r.jsxs)(n.p,{children:["A continu